import 'package:flutter/material.dart';import 'package:intl/intl.dart';import 'package:provider/provider.dart';import '../core/app_state.dart';
class HistoryScreen extends StatelessWidget{const HistoryScreen({super.key});@override Widget build(BuildContext c){final s=c.watch<AppState>();return Scaffold(appBar:AppBar(title:const Text('Local history'),actions:[TextButton.icon(onPressed:s.items.isEmpty?null:s.clearHistory,icon:const Icon(Icons.delete_outline),label:const Text('Clear'))]),body:s.items.isEmpty?const Center(child:Text('No operations yet.')):ListView.separated(padding:const EdgeInsets.all(24),itemCount:s.items.length,separatorBuilder:(_,__)=>const SizedBox(height:10),itemBuilder:(c,i){final x=s.items[i];return Card(child:ListTile(leading:CircleAvatar(child:Icon(x.success?Icons.check:Icons.error_outline)),title:Text('${x.action.toUpperCase()} · ${x.inputPath.split(RegExp(r'[\\/]')).last}'),subtitle:Text('${x.mode} · ${DateFormat.yMMMd().add_Hm().format(x.createdAt)}\n${x.outputPath}'),isThreeLine:true,trailing:Text(x.success?(x.result==null?'Done':'${x.result!.saving.toStringAsFixed(1)}%'):'Failed'));}));}}
